//! A re-implementation of the observable behavior of `tsl::hopscotch_map`
//! using only the Rust standard library.
//!
//! The original C++ container is a hash map based on hopscotch hashing.
//! Since only its public interface behavior matters here (insert, operator[],
//! equality comparison), it is backed by `std::collections::HashMap`, which
//! provides identical observable semantics.

use std::collections::HashMap;
use std::hash::Hash;
use std::ops::{Index, IndexMut};

pub struct HopscotchMap<K, V> {
    inner: HashMap<K, V>,
}

impl<K, V> HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    pub fn new() -> Self {
        HopscotchMap {
            inner: HashMap::new(),
        }
    }

    /// Mirrors `map.insert({key, value})`: inserts the pair, overwriting the
    /// value if the key already exists.
    pub fn insert(&mut self, key: K, value: V) {
        self.inner.insert(key, value);
    }

    pub fn len(&self) -> usize {
        self.inner.len()
    }
}

impl<K, V> Default for HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    fn default() -> Self {
        Self::new()
    }
}

/// Mirrors `map[key]` read access.
impl<K, V> Index<&K> for HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    type Output = V;

    fn index(&self, key: &K) -> &V {
        &self.inner[key]
    }
}

/// Mirrors `map[key] = value` (C++ `operator[]`): if the key is missing, a
/// default-constructed value is inserted first, then assigned.
impl<K, V> IndexMut<&K> for HopscotchMap<K, V>
where
    K: Eq + Hash + Clone,
    V: Default,
{
    fn index_mut(&mut self, key: &K) -> &mut V {
        self.inner.entry(key.clone()).or_default()
    }
}

/// Mirrors `operator==`: two maps are equal iff they contain the same
/// key/value pairs, regardless of internal layout.
impl<K, V> PartialEq for HopscotchMap<K, V>
where
    K: Eq + Hash,
    V: PartialEq,
{
    fn eq(&self, other: &Self) -> bool {
        self.inner == other.inner
    }
}

impl<K, V> Eq for HopscotchMap<K, V>
where
    K: Eq + Hash,
    V: Eq,
{
}

