use hopscotch_map::HopscotchMap;

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut count: i32 = 14;
    if args.len() > 1 && args[1] == "--a" {
        count = args[2].parse::<i32>().expect("invalid integer");
    }

    let mut map1: HopscotchMap<i32, i32> = HopscotchMap::new();
    let mut map2: HopscotchMap<i32, i32> = HopscotchMap::new();

    for i in 0..count {
        map1.insert(i, i * 11);
        map2.insert(i, i * 11);
    }

    // std::cout << bool prints "1" or "0".
    print!("{} ", (map1 == map2) as i32);
    map2[&0] = 999;
    println!("{}", (map1 == map2) as i32);
}

